from openpyxl import load_workbook

# Inspect formulas/structure without saving
wb = load_workbook('budget.xlsx', data_only=False)
print("Sheets:", wb.sheetnames)
for ws in wb.worksheets:
    print(f"\n=== Sheet: {ws.title} | dims: {ws.dimensions} | max_row={ws.max_row} max_col={ws.max_column}")
    for row in ws.iter_rows():
        for c in row:
            if c.value is not None:
                print(f"  {c.coordinate}: {repr(c.value)}")
EOF
